import { AfterViewInit, Component, DestroyRef, ElementRef, ViewChild, computed, inject, input, output, signal } from '@angular/core';
import { NgClass } from '@angular/common';
import { ApButtonComponent } from '../ap-button/ap-button.component';
import { ApIconComponent } from '../ap-icon/ap-icon.component';
import { ApIconBadgeComponent } from '../ap-icon-badge/ap-icon-badge.component';

export interface TabMenuItem {
  /** 頁籤識別值，變更頁籤時會透過此值通知外層。 */
  id: string;
  /** 頁籤顯示文字。 */
  label: string;
  /** 頁籤圖示名稱；未提供時不顯示圖示。 */
  icon?: string;
  /** 是否在頁籤圖示旁顯示徽章。 */
  hasBadge?: boolean;
  /** 是否停用此頁籤。 */
  disabled?: boolean;
}

/** 頁籤選取狀態使用的強調色。 */
export type TabMenuAccentColor = 'yellow' | 'orange' | 'slate';

/** 各強調色對應的選取狀態 Tailwind 樣式。 */
const activeClassMap: Record<TabMenuAccentColor, string> = {
  yellow: 'text-yellow-400 border-yellow-400',
  orange: 'text-orange-400 border-orange-400',
  slate: 'text-slate-400 border-slate-400',
};

/** 各強調色對應的未選取及 hover 狀態 Tailwind 樣式。 */
const inactiveClassMap: Record<TabMenuAccentColor, string> = {
  yellow: 'text-zinc-500 border-zinc-500 dark:hover:text-yellow-200 dark:hover:border-yellow-200 hover:text-yellow-300 hover:border-yellow-300',
  orange: 'text-zinc-500 border-zinc-500 dark:hover:text-orange-200 dark:hover:border-orange-200 hover:text-orange-300 hover:border-orange-300',
  slate: 'text-zinc-500 border-zinc-500 dark:hover:text-slate-300 dark:hover:border-slate-200 hover:text-slate-300 hover:border-slate-300',
};

@Component({
  selector: 'ap-tab-menu-icon',
  imports: [NgClass, ApButtonComponent, ApIconComponent, ApIconBadgeComponent],
  templateUrl: './ap-tab-menu-icon.component.html',
  styleUrls: ['./ap-tab-menu-icon.component.css']
})
export class ApTabMenuIconComponent implements AfterViewInit {
  /** 可水平捲動的頁籤容器。 */
  @ViewChild('tabContainer', { static: false })
  tabContainer!: ElementRef<HTMLDivElement>;

  /** 要顯示的頁籤項目。 */
  tabs = input<TabMenuItem[]>([
    { id: 'tab1', label: 'Tab 1', icon: 'star' },
    { id: 'tab2', label: 'Tab 2', icon: 'trophy' },
    { id: 'tab3', label: 'Tab 3', icon: 'sparkles' },
  ]);
  /** 目前選取的頁籤 ID。 */
  selectedTab = input<string>('tab1');
  /** 選取及 hover 狀態使用的強調色。 */
  accentColor = input<TabMenuAccentColor>('yellow');
  /** 頁籤排列方式。 */
  justify = input<'center' | 'start'>('center');
  /** 使用者選取頁籤時發出的頁籤 ID。 */
  tabChange = output<string>();

  /** 螢幕是否符合手機版寬度。 */
  isMobile = signal(false);
  /** 容器是否仍可向左捲動。 */
  canScrollLeft = signal(false);
  /** 容器是否仍可向右捲動。 */
  canScrollRight = signal(true);
  /** 頁籤數量較多時顯示溢位提示。 */
  showOverflowHint = computed(
    () => this.tabs().length > (this.isMobile() ? 10 : 14)
  );

  /** 監聽容器捲動與螢幕寬度變化所需的資源。 */
  private destroyRef = inject(DestroyRef);
  private mediaQueryList?: MediaQueryList;
  private mediaQueryHandler?: (event: MediaQueryListEvent) => void;

  /** 拖曳捲動時使用的起點、捲動位置及狀態。 */
  private isDragging = false;
  private startX = 0;
  private scrollLeft = 0;
  private hasDragged = false;

  /** 更新左右捲動提示，並在元件銷毀時移除監聽器。 */
  private scrollHandler = () => {
    if (!this.tabContainer?.nativeElement) return;
    const el = this.tabContainer.nativeElement;
    this.canScrollLeft.set(el.scrollLeft > 1);
    this.canScrollRight.set(el.scrollLeft + el.clientWidth < el.scrollWidth - 1);
  };

  constructor() {
    // 初始化手機版斷點監聽。
    this.setupMediaQuery();
  }

  ngAfterViewInit() {
    const el = this.tabContainer?.nativeElement;
    if (!el) return;
    // 容器完成初始化後才可監聽實際捲動位置。
    el.addEventListener('scroll', this.scrollHandler, { passive: true });
    this.destroyRef.onDestroy(() => {
      el.removeEventListener('scroll', this.scrollHandler);
    });
  }

  onTabClick(tabId: string, tabEl?: HTMLElement) {
    // 拖曳手勢結束後短暫抑制 click，避免誤觸切換頁籤。
    if (!this.hasDragged) {
      this.tabChange.emit(tabId);
      if (tabEl && this.tabContainer?.nativeElement) {
        this.scrollTabIntoCenter(tabEl);
      }
    }
  }

  isSelected(tabId: string): boolean {
    // 以輸入的 selectedTab 作為目前選取狀態來源。
    return this.selectedTab() === tabId;
  }

  /** 依方向捲動頁籤列，讓使用者可透過按鈕瀏覽隱藏的頁籤。 */
  scrollTabs(direction: 'left' | 'right') {
    const container = this.tabContainer?.nativeElement;
    if (!container) return;

    container.scrollBy({
      left: direction === 'left' ? -container.clientWidth * 0.75 : container.clientWidth * 0.75,
      behavior: 'smooth'
    });
  }

  getSelectedLabel(): string {
    // 找不到目前頁籤時回傳空字串。
    const selected = this.selectedTab();
    const tab = this.tabs().find((item) => item.id === selected);
    return tab?.label ?? '';
  }

  getActiveClasses(): string {
    // 取得目前強調色的選取樣式。
    return activeClassMap[this.accentColor()];
  }

  getInactiveClasses(): string {
    // 取得目前強調色的未選取與 hover 樣式。
    return inactiveClassMap[this.accentColor()];
  }

  onMouseDown(event: MouseEvent) {
    // 記錄滑鼠拖曳起點，並切換游標提示。
    this.isDragging = true;
    this.hasDragged = false;
    this.startX = event.pageX - this.tabContainer.nativeElement.offsetLeft;
    this.scrollLeft = this.tabContainer.nativeElement.scrollLeft;
    this.tabContainer.nativeElement.style.cursor = 'grabbing';
    event.preventDefault();
  }

  onMouseMove(event: MouseEvent) {
    if (!this.isDragging) return;
    // 依滑鼠位移更新水平捲動位置；超過門檻才視為拖曳。
    event.preventDefault();
    const x = event.pageX - this.tabContainer.nativeElement.offsetLeft;
    const walk = (x - this.startX) * 2;
    this.tabContainer.nativeElement.scrollLeft = this.scrollLeft - walk;
    if (Math.abs(walk) > 5) {
      this.hasDragged = true;
    }
  }

  onMouseUp(event: MouseEvent) {
    // 結束拖曳，稍後清除拖曳標記以阻擋緊接著發生的 click。
    this.isDragging = false;
    this.tabContainer.nativeElement.style.cursor = 'grab';
    setTimeout(() => {
      this.hasDragged = false;
    }, 100);
  }

  onTouchStart(event: TouchEvent) {
    // 記錄觸控起點，供觸控拖曳捲動使用。
    this.isDragging = true;
    this.hasDragged = false;
    this.startX = event.touches[0].pageX - this.tabContainer.nativeElement.offsetLeft;
    this.scrollLeft = this.tabContainer.nativeElement.scrollLeft;
  }

  onTouchMove(event: TouchEvent) {
    if (!this.isDragging) return;
    // 依手指位移捲動頁籤列，並判定是否已形成拖曳。
    const x = event.touches[0].pageX - this.tabContainer.nativeElement.offsetLeft;
    const walk = (x - this.startX) * 2;
    this.tabContainer.nativeElement.scrollLeft = this.scrollLeft - walk;
    if (Math.abs(walk) > 5) {
      this.hasDragged = true;
    }
  }

  onTouchEnd(event: TouchEvent) {
    // 結束觸控拖曳，短暫抑制由手勢產生的 click。
    this.isDragging = false;
    setTimeout(() => {
      this.hasDragged = false;
    }, 100);
  }

  private scrollTabIntoCenter(tabEl: HTMLElement) {
    // 將剛選取的頁籤平滑捲動至容器中央。
    const container = this.tabContainer.nativeElement;
    const targetLeft =
      tabEl.offsetLeft - (container.clientWidth - tabEl.clientWidth) / 2;
    container.scrollTo({
      left: targetLeft,
      behavior: 'smooth'
    });
  }

  private setupMediaQuery() {
    // SSR 或不支援 matchMedia 的環境預設使用非手機版狀態。
    if (typeof window === 'undefined' || !window.matchMedia) {
      this.isMobile.set(false);
      return;
    }

    // 以 640px 作為手機版與較大螢幕的斷點，並在銷毀時解除監聽。
    this.mediaQueryList = window.matchMedia('(max-width: 639px)');
    this.isMobile.set(this.mediaQueryList.matches);
    this.mediaQueryHandler = (event: MediaQueryListEvent) => {
      this.isMobile.set(event.matches);
    };
    this.mediaQueryList.addEventListener('change', this.mediaQueryHandler);

    this.destroyRef.onDestroy(() => {
      if (this.mediaQueryList && this.mediaQueryHandler) {
        this.mediaQueryList.removeEventListener('change', this.mediaQueryHandler);
      }
    });
  }
}
