import { Component, Input } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ApIconComponent } from '../ap-icon/ap-icon.component';
import { TagAccentColor, TagVariant } from './ap-tag.interface';

@Component({
  selector: 'ap-tag',
  imports: [CommonModule, ApIconComponent],
  host: { display: 'inline-block' },
  templateUrl: './ap-tag.component.html',
})
export class ApTagComponent {
  @Input() label: string = '';
  @Input() accentColor: TagAccentColor = 'orange';
  @Input() variant: TagVariant = 'default';
  @Input() icon?: string;
  @Input() rounded: boolean = false;

  get tagClasses(): string {
    const classes: string[] = [
      'inline-flex', 'items-center', 'gap-1', 'px-2', 'py-1', 'text-xs', 'font-semibold',];
    if (this.variant === 'pill' || this.rounded) {
      classes.push('rounded-full');
    } else {
      classes.push('rounded-md');
    }

    switch (this.accentColor) {
      case 'orange':
        classes.push('bg-orange-500/20', 'text-orange-500', 'dark:text-orange-300'
        );
        break;

      case 'green':
        classes.push('bg-green-500/20', 'text-green-500', 'dark:text-green-300'
        );
        break;

      case 'sky':
        classes.push('bg-sky-500/20', 'text-sky-500', 'dark:text-sky-300');
        break;

      case 'yellow':
        classes.push('text-yellow-500', 'bg-yellow-500/20', 'dark:text-yellow-300'
        );
        break;

      case 'red':
        classes.push('bg-red-500', 'text-red-500', 'dark:text-red-100');
        break;

      case 'zinc':
        classes.push('bg-zinc-500/20', 'text-zinc-500', 'dark:text-zinc-300');
        break;

    }

    return classes.join(' ');
  }

  get iconClasses(): string {
    return 'w-3 h-3';
  }
}
